213:   const html = fs.readFileSync(htmlPath, 'utf8');
214:   const dom = new JSDOM(html, {
215:     url: 'http://localhost/#' + initialRoute,
216:     runScripts: 'outside-only'
217:   });
218:   const { window } = dom;
219: 
220:   window.__TEST_M3__ = true;
221:   installScrollMocks(window);
222:   setupLayoutMock(window);
223: 
224:   const configCode = fs.readFileSync(configPath, 'utf8');
225:   const navCode = fs.readFileSync(navPath, 'utf8');
226:   const appCode = fs.readFileSync(appPath, 'utf8');
227: 
228:   window.eval(configCode);
229:   window.eval(navCode);
230:   window.eval(appCode);
231: 
232:   window.CinejoyApp.init();
233: 
234:   return { dom, window, app: window.CinejoyApp, nav: window.SpatialNav };
235: }
