/**
 * Forensic Anti-Cheat & Adversarial Stress Test
 * Executed independently by auditor_m3
 */

const assert = require('assert');
const fs = require('fs');
const path = require('path');

let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
  }
}

console.log('========================================================================');
console.log('   AUDITOR_M3: INDEPENDENT FORENSIC INTEGRITY & ADVERSARIAL STRESS TEST  ');
console.log('========================================================================\n');

const dom = new JSDOM('<!DOCTYPE html><html><body><div id="root"></div></body></html>', {
  url: 'http://localhost/#home',
  runScripts: 'outside-only'
});
const { window } = dom;

// Load navigation.js directly
const navSource = fs.readFileSync(path.resolve(__dirname, '../../../app/js/navigation.js'), 'utf8');
window.eval(navSource);
const nav = window.SpatialNav;

assert(nav, 'SpatialNav must be exported and loaded');

let testCount = 0;
let passCount = 0;

function runTest(name, fn) {
  testCount++;
  try {
    fn();
    passCount++;
    console.log(`  ✓ PASS [T${testCount}] ${name}`);
  } catch (err) {
    console.error(`  ✗ FAIL [T${testCount}] ${name}`);
    console.error(`    ${err.message}`);
    throw err;
  }
}

// -----------------------------------------------------------------------------
// Test 1: Authentic Vector Calculation - Dynamic Coordinate Shift
// -----------------------------------------------------------------------------
runTest('Dynamic Coordinate Inversion (Proves algorithmic calculation, not hardcoded order)', () => {
  const container = window.document.createElement('div');
  container.className = 'view active';
  window.document.body.appendChild(container);

  // Element Origin at (100, 100)
  const origin = window.document.createElement('button');
  origin.setAttribute('data-nav', 'true');
  origin.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 50, height: 50 }));
  container.appendChild(origin);

  // Candidate 1 at (200, 100)
  const cand1 = window.document.createElement('button');
  cand1.id = 'cand1';
  cand1.setAttribute('data-nav', 'true');
  cand1.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 100, width: 50, height: 50 }));
  container.appendChild(cand1);

  // Candidate 2 at (400, 100)
  const cand2 = window.document.createElement('button');
  cand2.id = 'cand2';
  cand2.setAttribute('data-nav', 'true');
  cand2.setAttribute('data-mock-rect', JSON.stringify({ left: 400, top: 100, width: 50, height: 50 }));
  container.appendChild(cand2);

  // Step 1: Normal positions - moving right must pick cand1 (closer)
  nav.setFocus(origin);
  let best = nav.findBestCandidate(origin, 'right');
  assert.strictEqual(best, cand1, 'Closer element cand1 must be picked');

  // Step 2: Invert coordinates dynamically without changing DOM order
  // Cand1 moved to 500, Cand2 moved to 180
  cand1.setAttribute('data-mock-rect', JSON.stringify({ left: 500, top: 100, width: 50, height: 50 }));
  cand2.setAttribute('data-mock-rect', JSON.stringify({ left: 180, top: 100, width: 50, height: 50 }));

  best = nav.findBestCandidate(origin, 'right');
  assert.strictEqual(best, cand2, 'Algorithm must adapt to inverted coordinates and pick cand2 (now closer)');
});

// -----------------------------------------------------------------------------
// Test 2: Angle Cone Boundary Threshold Verification (60° and 85°)
// -----------------------------------------------------------------------------
runTest('Angular Beam Boundary Thresholds (59° vs 61° vs 86°)', () => {
  const container = window.document.createElement('div');
  container.className = 'view active';
  window.document.body.appendChild(container);

  const origin = window.document.createElement('button');
  origin.setAttribute('data-nav', 'true');
  origin.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 10, height: 10 }));
  container.appendChild(origin);

  // For dx = 100, dy = dx * tan(theta)
  // tan(59°) = 1.66428 -> dy = 166 (inside 60° cone)
  // tan(61°) = 1.80404 -> dy = 180 (outside 60° cone, inside 85° cone)
  // tan(86°) = 14.3006 -> dy = 1435 (outside 85° cone)

  const cand59 = window.document.createElement('button');
  cand59.setAttribute('data-nav', 'true');
  cand59.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 100 + 166, width: 10, height: 10 }));
  container.appendChild(cand59);

  // With only cand59 in the direction, it must be selected in Pass 1
  let selected = nav.findBestCandidate(origin, 'right', [origin, cand59]);
  assert.strictEqual(selected, cand59, 'Candidate at 59° must qualify in Pass 1');

  // Cand61: at 61°
  const cand61 = window.document.createElement('button');
  cand61.setAttribute('data-nav', 'true');
  cand61.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 100 + 180, width: 10, height: 10 }));
  container.appendChild(cand61);

  // When cand59 and cand61 compete:
  // cand59 qualifies in Pass 1 (strict 60°), while cand61 is excluded from Pass 1.
  // Therefore cand59 MUST win, even if cand61 were somehow closer in some metric.
  selected = nav.findBestCandidate(origin, 'right', [origin, cand59, cand61]);
  assert.strictEqual(selected, cand59, 'Pass 1 (60°) must filter cand61 and pick cand59');

  // Cand86: at 86° (> 85° fallback cone)
  const cand86 = window.document.createElement('button');
  cand86.setAttribute('data-nav', 'true');
  cand86.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 100 + 1435, width: 10, height: 10 }));
  container.appendChild(cand86);

  // If only cand86 exists, it must return null (rejected by both Pass 1 and Pass 2)
  selected = nav.findBestCandidate(origin, 'right', [origin, cand86]);
  assert.strictEqual(selected, null, 'Candidate at 86° must be completely rejected by both passes');
});

// -----------------------------------------------------------------------------
// Test 3: Strict Focus Trapping Isolation
// -----------------------------------------------------------------------------
runTest('Focus Trapping Complete Boundary Isolation', () => {
  const modal = window.document.createElement('div');
  modal.id = 'modal-overlay';
  const modalBtn = window.document.createElement('button');
  modalBtn.setAttribute('data-nav', 'true');
  modalBtn.setAttribute('data-mock-rect', JSON.stringify({ left: 500, top: 500, width: 100, height: 50 }));
  modal.appendChild(modalBtn);
  window.document.body.appendChild(modal);

  const outsideBtn = window.document.createElement('button');
  outsideBtn.setAttribute('data-nav', 'true');
  // Placed right next to modalBtn (dx = 5px)
  outsideBtn.setAttribute('data-mock-rect', JSON.stringify({ left: 605, top: 500, width: 100, height: 50 }));
  window.document.body.appendChild(outsideBtn);

  nav.trap(modal);
  nav.setFocus(modalBtn);

  // Move right - should NOT jump to outsideBtn
  const result = nav.move('right');
  assert.strictEqual(result, null, 'Modal trap must strictly block navigation to outside element');
  assert.strictEqual(nav.getCurrentFocus(), modalBtn, 'Focus must remain inside trapped container');

  nav.untrap();
});

// -----------------------------------------------------------------------------
// Test 4: Orthogonal Weighting Arithmetic Verification
// -----------------------------------------------------------------------------
runTest('Orthogonal 2.5x Weighting Arithmetic Proof', () => {
  // Let origin be at (100, 100, 50, 50)
  // Candidate A: dx = 100, dy = 0 (direct) -> score = 100 + 2.5*0 - bonus(50*1.5) = 100 - 75 = 25
  // Candidate B: dx = 20, dy = 60 (diagonal, no overlap) -> primary = 20, dy = 60, dOrth = 60 - 50 = 10 + delta*0.5 = 10 + 30 = 40
  // Score B = 20 + 2.5*40 = 120
  // Even though B is physically closer in Euclidean distance (sqrt(20^2 + 60^2) = 63.2 vs 100),
  // Candidate A must win because orthogonal penalty heavily penalizes off-axis elements.
  const container = window.document.createElement('div');
  container.className = 'view active';
  window.document.body.appendChild(container);

  const origin = window.document.createElement('button');
  origin.setAttribute('data-nav', 'true');
  origin.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 50, height: 50 }));
  container.appendChild(origin);

  const candA = window.document.createElement('button');
  candA.setAttribute('data-nav', 'true');
  candA.setAttribute('data-mock-rect', JSON.stringify({ left: 250, top: 100, width: 50, height: 50 }));
  container.appendChild(candA);

  const candB = window.document.createElement('button');
  candB.setAttribute('data-nav', 'true');
  candB.setAttribute('data-mock-rect', JSON.stringify({ left: 170, top: 170, width: 50, height: 50 }));
  container.appendChild(candB);

  const best = nav.findBestCandidate(origin, 'right', [origin, candA, candB]);
  assert.strictEqual(best, candA, 'Direct aligned candidate A must win over Euclidean-closer off-axis candidate B');
});

console.log(`\n========================================================================`);
console.log(`AUDITOR FORENSIC CHECKS: ${passCount} / ${testCount} PASSED`);
console.log(`========================================================================\n`);

