// -----------------------------------------------------------------------------
// Test 5: Complex Non-Uniform Grid Navigation
// -----------------------------------------------------------------------------
runTest('Non-Uniform Irregular Grid Navigation (5x5 matrix with jitter)', () => {
  const container = window.document.createElement('div');
  container.className = 'view active';
  window.document.body.appendChild(container);

  const grid = [];
  for (let r = 0; r < 5; r++) {
    grid[r] = [];
    for (let c = 0; c < 5; c++) {
      const btn = window.document.createElement('button');
      btn.id = `grid_${r}_${c}`;
      btn.setAttribute('data-nav', 'true');
      // Add slight non-uniform jitter to coordinates
      const left = 100 + c * 200 + (r % 2 === 0 ? 5 : -5);
      const top = 100 + r * 150 + (c % 2 === 0 ? 3 : -3);
      btn.setAttribute('data-mock-rect', JSON.stringify({ left, top, width: 80, height: 60 }));
      container.appendChild(btn);
      grid[r][c] = btn;
    }
  }

  // Start at (0, 0)
  nav.setFocus(grid[0][0]);
  assert.strictEqual(nav.getCurrentFocus(), grid[0][0]);

  // Navigate step-by-step right across entire row
  for (let c = 1; c < 5; c++) {
    const moved = nav.move('right');
    assert.strictEqual(moved, grid[0][c], `Moving right from col ${c-1} must reach col ${c}`);
  }

  // Navigate step-by-step down across entire column
  for (let r = 1; r < 5; r++) {
    const moved = nav.move('down');
    assert.strictEqual(moved, grid[r][4], `Moving down from row ${r-1} must reach row ${r}`);
  }

  // Navigate step-by-step left across bottom row
  for (let c = 3; c >= 0; c--) {
    const moved = nav.move('left');
    assert.strictEqual(moved, grid[4][c], `Moving left must reach col ${c}`);
  }

  // Navigate step-by-step up across first column
  for (let r = 3; r >= 0; r--) {
    const moved = nav.move('up');
    assert.strictEqual(moved, grid[r][0], `Moving up must reach row ${r}`);
  }
});

// -----------------------------------------------------------------------------
// Test 6: Distance Overlap Bonus Threshold (1.5x up to 120px cap)
// -----------------------------------------------------------------------------
runTest('Distance Overlap Bonus Capping at 120px', () => {
  const container = window.document.createElement('div');
  container.className = 'view active';
  window.document.body.appendChild(container);

  // Origin at (100, 100) with height 200
  const origin = window.document.createElement('button');
  origin.setAttribute('data-nav', 'true');
  origin.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 50, height: 200 }));
  container.appendChild(origin);

  // Cand1: overlap = 120px (height 120) at left=300, top=100
  // Cand2: overlap = 200px (height 200) at left=300, top=100
  // Both have primary distance = 150, orthogonal distance = 0
  // But cand2's bonus is capped at 120 * 1.5 = 180, so both get identical max bonus!
  const cand1 = window.document.createElement('button');
  cand1.id = 'overlap_120';
  cand1.setAttribute('data-nav', 'true');
  cand1.setAttribute('data-mock-rect', JSON.stringify({ left: 300, top: 100, width: 50, height: 120 }));
  container.appendChild(cand1);

  const cand2 = window.document.createElement('button');
  cand2.id = 'overlap_200';
  cand2.setAttribute('data-nav', 'true');
  cand2.setAttribute('data-mock-rect', JSON.stringify({ left: 300, top: 100, width: 50, height: 200 }));
  container.appendChild(cand2);

  // Tie-breaking applies since score difference is 0 (< 1.0)
  const selected = nav.findBestCandidate(origin, 'right', [origin, cand1, cand2]);
  assert(selected === cand1 || selected === cand2, 'One of the tied overlap candidates must be chosen');
});

// -----------------------------------------------------------------------------
// Test 7: Memory Cascade Resolution Fallback
// -----------------------------------------------------------------------------
runTest('6-Stage Memory Cascade Fallback (Detached Node -> ID -> Group+Index)', () => {
  const viewHome = window.document.createElement('div');
  viewHome.id = 'view-home';
  viewHome.className = 'view active';
  window.document.body.appendChild(viewHome);

  const card = window.document.createElement('div');
  card.id = 'movie-101';
  card.setAttribute('data-nav', 'true');
  card.setAttribute('data-nav-group', 'trending');
  card.setAttribute('data-nav-index', '3');
  card.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 200, width: 100, height: 100 }));
  viewHome.appendChild(card);

  nav.setFocus(card);
  nav.saveFocus('home');

  // Stage 1: Card exists directly -> restores direct node
  let restored = nav.restoreFocus('home');
  assert.strictEqual(restored, card, 'Stage 1: direct node must be restored');

  // Stage 2: Card removed, replacement with same ID added
  card.remove();
  const cardWithSameId = window.document.createElement('div');
  cardWithSameId.id = 'movie-101';
  cardWithSameId.setAttribute('data-nav', 'true');
  cardWithSameId.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 200, width: 100, height: 100 }));
  viewHome.appendChild(cardWithSameId);

  restored = nav.restoreFocus('home');
  assert.strictEqual(restored, cardWithSameId, 'Stage 2: node with same ID must be restored');

  // Stage 3: Card ID changed, replacement with same group and index added
  cardWithSameId.remove();
  const cardWithSameGroup = window.document.createElement('div');
  cardWithSameGroup.id = 'movie-regenerated';
  cardWithSameGroup.setAttribute('data-nav', 'true');
  cardWithSameGroup.setAttribute('data-nav-group', 'trending');
  cardWithSameGroup.setAttribute('data-nav-index', '3');
  cardWithSameGroup.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 200, width: 100, height: 100 }));
  viewHome.appendChild(cardWithSameGroup);

  restored = nav.restoreFocus('home');
  assert.strictEqual(restored, cardWithSameGroup, 'Stage 3: node matching group and index must be restored');
});

// -----------------------------------------------------------------------------
// Test 8: Throttle Timing Enforcement
// -----------------------------------------------------------------------------
runTest('Directional Movement Key Repeat Throttle (60ms enforcement)', () => {
  nav.init();
  const container = window.document.createElement('div');
  container.className = 'view active';
  window.document.body.appendChild(container);

  const a = window.document.createElement('button');
  a.setAttribute('data-nav', 'true');
  a.setAttribute('data-mock-rect', JSON.stringify({ left: 100, top: 100, width: 50, height: 50 }));
  container.appendChild(a);

  const b = window.document.createElement('button');
  b.setAttribute('data-nav', 'true');
  b.setAttribute('data-mock-rect', JSON.stringify({ left: 200, top: 100, width: 50, height: 50 }));
  container.appendChild(b);

  const c = window.document.createElement('button');
  c.setAttribute('data-nav', 'true');
  c.setAttribute('data-mock-rect', JSON.stringify({ left: 300, top: 100, width: 50, height: 50 }));
  container.appendChild(c);

  nav.setFocus(a);
  nav.resetThrottle();

  // First keypress: should move to B
  const ev1 = { keyCode: 39, preventDefault: () => {} };
  nav.handleKeyDown(ev1);
  assert.strictEqual(nav.getCurrentFocus(), b, 'First keypress must immediately move to B');

  // Immediate second keypress (0ms elapsed): MUST be throttled/discarded
  const ev2 = { keyCode: 39, preventDefault: () => {} };
  nav.handleKeyDown(ev2);
  assert.strictEqual(nav.getCurrentFocus(), b, 'Immediate keypress (<60ms) must be discarded by throttle');

  // Reset throttle: third keypress now proceeds to C
  nav.resetThrottle();
  const ev3 = { keyCode: 39, preventDefault: () => {} };
  nav.handleKeyDown(ev3);
  assert.strictEqual(nav.getCurrentFocus(), c, 'Keypress after throttle reset must move to C');
});

console.log(`\n========================================================================`);
console.log(`AUDITOR FORENSIC CHECKS: ${passCount} / ${testCount} PASSED`);
console.log(`========================================================================\n`);

